<?php
$line = trim(fgets(STDIN));
list($n, $k, $l, $c, $d, $p, $nl, $np) = preg_split('/\s+/', $line);

$n = (int)$n;
$k = (int)$k;
$l = (int)$l;
$c = (int)$c;
$d = (int)$d;
$p = (int)$p;
$nl = (int)$nl;
$np = (int)$np;

$drinkToasts = intdiv($k * $l, $nl);
$limeToasts = $c * $d;
$saltToasts = intdiv($p, $np);

$minToasts = min($drinkToasts, $limeToasts, $saltToasts);
$result = intdiv($minToasts, $n);

echo $result . "\n";
